// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "name", "symbol"); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.deal(nonOwner, 0);
        vm.prank(c.owner());
        c.mintToken(nonOwner, burnAmount);
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(nonOwner);
        bool ok;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(!ok && totalSupplyAfter == totalSupplyBefore);
    }
}
